type WorkItemStatus = 'Not started' | 'In progress' | 'At risk' | 'Complete';

interface WorkItem {
  id: string;
  name: string;
  status: WorkItemStatus;
  owner: string;
  dueDate: string;
  children?: WorkItem[];
}

